      },
      {
        "event_id": "lite_evt_00281",
        "explanation": "The doctor reinforced that confirmed pulmonary infection plus oxygen need made home discharge unsafe that night.",
        "quote": "今晚绝对不能回家"
      }
    ],
    "patient_family_realworld_adaptation": [
      {
        "event_id": "lite_evt_00211",
        "explanation": "The doctor adapted to caregiver fatigue and overnight ED observation with a practical nursing-notification plan.",
        "quote": "我夜里可能会眯一下"
      }
    ]
  },
  "dimension_ratings": {
    "actionability_responsibility_chain": "unsafe",
